import { NextResponse } from "next/server";
import { createPublicClient, http } from "viem";

const ORACLE_ABI = [
  {
    type: "function",
    name: "latestRoundData",
    inputs: [],
    outputs: [
      { name: "roundId", type: "uint80" },
      { name: "answer", type: "int256" },
      { name: "startedAt", type: "uint256" },
      { name: "updatedAt", type: "uint256" },
      { name: "answeredInRound", type: "uint80" },
    ],
    stateMutability: "view",
  },
] as const;

const BTC_ORACLE = "0x4bE899cF15a212fd6123E4A0E6e1B4925f493B96" as const;
const ETH_ORACLE = "0x9674Dbe42f9996e1470F8eC15a6D0aebA4a93AEb" as const;

const MAX_POINTS = 120;

// Server-side price history cache
const priceHistory: { BTC: number[]; ETH: number[] } = { BTC: [], ETH: [] };
let collectorRunning = false;

const client = createPublicClient({
  transport: http("https://carrot.megaeth.com/rpc"),
});

async function fetchOraclePrice(oracle: `0x${string}`): Promise<number> {
  const [, answer] = await client.readContract({
    address: oracle,
    abi: ORACLE_ABI,
    functionName: "latestRoundData",
  });
  return Number(answer) / 1e8;
}

function startCollector() {
  if (collectorRunning) return;
  collectorRunning = true;

  const collect = async () => {
    try {
      const [btc, eth] = await Promise.all([
        fetchOraclePrice(BTC_ORACLE),
        fetchOraclePrice(ETH_ORACLE),
      ]);

      if (btc > 0) {
        priceHistory.BTC.push(btc);
        if (priceHistory.BTC.length > MAX_POINTS) priceHistory.BTC.shift();
      }
      if (eth > 0) {
        priceHistory.ETH.push(eth);
        if (priceHistory.ETH.length > MAX_POINTS) priceHistory.ETH.shift();
      }
    } catch (e) {
      // silent
    }
  };

  collect();
  setInterval(collect, 500);
}

// Start collecting on first import
startCollector();

export async function GET() {
  return NextResponse.json({
    BTC: priceHistory.BTC,
    ETH: priceHistory.ETH,
    timestamp: Date.now(),
  });
}
